public class STTAliyunClient
implements STTClient {
    private static final AudioFormat FORMAT = new AudioFormat(16000.0f, 16, 1, true, false);
    private static final Duration MAX_TIMEOUT = Duration.ofSeconds(15L);
    private static final String TOKEN = "X-NLS-Token";
    private static final int OK_STATUS = 20000000;
    private final HttpClient httpClient;
    private final STTAliyunSite site;

    public STTAliyunClient(HttpClient httpClient, STTAliyunSite site) {
        this.httpClient = httpClient;
        this.site = site;
    }

    @Override
    public void startRecord(STTConfig config, ResponseCallback<String> callback) {
        Mixer.Info info = MicrophoneManager.getMicrophoneInfo(FORMAT);
        if (info == null) {
            callback.onFailure(null, new Throwable("No suitable microphone found"), 5);
            return;
        }
        URI uri = URI.create(this.site.url());
        MicrophoneManager.startRecord(info.getName(), FORMAT, data -> {
            HttpRequest request = HttpRequest.newBuilder().uri(uri).header(TOKEN, this.site.getSecretKey()).header("Content-Type", MediaType.OCTET_STREAM.toString()).POST(HttpRequest.BodyPublishers.ofByteArray(data)).timeout(MAX_TIMEOUT).build();
            this.httpClient.sendAsync(request, HttpResponse.BodyHandlers.ofString()).whenComplete((response, throwable) -> this.handle(callback, (HttpResponse<String>)response, (Throwable)throwable, request));
        });
    }

    private void handle(ResponseCallback<String> callback, HttpResponse<String> response, Throwable throwable, HttpRequest request) {
        this.handleResponse(callback, response, throwable, request, message -> {
            if (message.getStatus() == 20000000) {
                callback.onSuccess(message.getResult());
            } else {
                callback.onFailure(request, new Throwable(message.getMessage()), 1);
            }
        }, (Type)((Object)Message.class));
    }

    @Override
    public void stopRecord(STTConfig config, ResponseCallback<String> callback) {
        MicrophoneManager.stopRecord();
    }
}

