public class STTPlayer2Client
implements STTClient {
    private static final Duration MAX_TIMEOUT = Duration.ofSeconds(15L);
    private static final String START_URL = "/start";
    private static final String STOP_URL = "/stop";
    private static final String START_REQUEST_BODY = "{\"timeout\":30}";
    private final HttpClient httpClient;
    private final STTPlayer2Site site;

    public STTPlayer2Client(HttpClient httpClient, STTPlayer2Site site) {
        this.httpClient = httpClient;
        this.site = site;
    }

    @Override
    public void startRecord(STTConfig config, ResponseCallback<String> callback) {
        URI uri = URI.create(this.site.url() + START_URL);
        HttpRequest.Builder builder = HttpRequest.newBuilder().header("Content-Type", MediaType.JSON_UTF_8.toString()).POST(HttpRequest.BodyPublishers.ofString(START_REQUEST_BODY)).timeout(MAX_TIMEOUT).uri(uri);
        this.site.headers().forEach(builder::header);
        HttpRequest httpRequest = builder.build();
        this.httpClient.sendAsync(httpRequest, HttpResponse.BodyHandlers.ofString()).whenComplete((response, throwable) -> this.handleStart(callback, (HttpResponse<String>)response, (Throwable)throwable, httpRequest));
    }

    private void handleStart(ResponseCallback<String> callback, HttpResponse<String> response, Throwable throwable, HttpRequest request) {
        this.handleResponse(callback, response, throwable, request, message -> {}, (Type)((Object)Message.class));
    }

    @Override
    public void stopRecord(STTConfig config, ResponseCallback<String> callback) {
        URI uri = URI.create(this.site.url() + STOP_URL);
        HttpRequest.Builder builder = HttpRequest.newBuilder().header("Content-Type", MediaType.JSON_UTF_8.toString()).POST(HttpRequest.BodyPublishers.noBody()).timeout(MAX_TIMEOUT).uri(uri);
        this.site.headers().forEach(builder::header);
        HttpRequest httpRequest = builder.build();
        this.httpClient.sendAsync(httpRequest, HttpResponse.BodyHandlers.ofString()).whenComplete((response, throwable) -> this.handleStop(callback, (HttpResponse<String>)response, (Throwable)throwable, httpRequest));
    }

    private void handleStop(ResponseCallback<String> callback, HttpResponse<String> response, Throwable throwable, HttpRequest request) {
        this.handleResponse(callback, response, throwable, request, message -> callback.onSuccess(message.getText()), (Type)((Object)Message.class));
    }
}

